USE acore_world;

-- ============================================================
-- Lane creep waves: 6 custom minion entries (melee/caster/siege x
-- Alliance/Horde), their data-driven config, and placeholder lane
-- waypoint paths (straight line between the existing tower positions --
-- to be replaced later with real .gps-walked waypoints).
--
-- Levels are pinned to 80 (matching current tower/test-character level),
-- NOT the source templates' original levels -- the engine's aggro-range
-- formula caps out at -25 levels difference, so a low-level source
-- template would barely aggro level-80 players. Revisit if/when testing
-- at a different level cap (see .github/MOBA_GUIDE.md).
-- ============================================================

DELETE FROM `creature_template` WHERE `entry` IN (900010, 900011, 900012, 900013, 900014, 900015, 900016, 900017);

