-- Fix: BaseAttackTime wasn't set on the creep entries (defaulted to schema's
-- 0), which breaks melee auto-attack timing. Towers never hit this since
-- they never auto-attack (REACT_PASSIVE).
UPDATE creature_template SET BaseAttackTime = 2000, RangeAttackTime = 2000
WHERE entry IN (900010, 900011, 900012, 900013, 900014, 900015);

-- Make minions run their lane path (and while chasing), not walk.
UPDATE waypoint_data SET move_type = 1 WHERE id IN (900100, 900101);

-- Minion health/armor: were full level-80-raid-trash stats (5342/3739 HP,
-- 9729/7822 armor before modifiers). First-pass tuning down so fights
-- resolve quickly and mutual armor doesn't blunt most of the damage.
-- Siege keeps 3x melee/caster's HealthModifier (proportional to the old
-- 3-vs-1 ratio), same ArmorModifier reduction as everyone else.
UPDATE creature_template SET HealthModifier = 0.05, ArmorModifier = 0.1
WHERE entry IN (900010, 900011, 900012, 900013); -- melee + caster

UPDATE creature_template SET HealthModifier = 0.15, ArmorModifier = 0.1
WHERE entry IN (900014, 900015); -- siege


-- ============================================================
-- Formation fix: melee needs a second distinct entry (900016/900017)
-- since one creature entry can't have two different default waypoint
-- paths, and both melee spawns previously shared 900010/900011. Each
-- formation slot (melee-left, melee-right, siege) now gets its own
-- duplicate waypoint path with node 1 positioned exactly at its spawn
-- offset, so nothing needs to backtrack to a shared node 0 anymore
-- (that backtracking was the root cause of casters ending up ahead of
-- melee, melee stacking, and units crossing paths). Caster keeps the
-- original path (900100/900101) since its formation offset is zero.
-- ============================================================

DELETE FROM `creature_template` WHERE `entry` IN (900016, 900017);
INSERT INTO `creature_template`
(`entry`, `name`, `subname`, `minlevel`, `maxlevel`, `faction`, `npcflag`,
 `speed_walk`, `speed_run`, `rank`, `unit_class`, `unit_flags`, `unit_flags2`,
 `type`, `type_flags`, `MovementType`, `HealthModifier`, `ArmorModifier`,
 `RegenHealth`, `CreatureImmunitiesId`, `flags_extra`, `ScriptName`, `VerifiedBuild`)
VALUES
