UPDATE creature_template SET BaseAttackTime = 2000, RangeAttackTime = 2000
WHERE entry IN (900016, 900017);

-- Reassign existing melee/siege entries to their new dedicated formation paths.
UPDATE mod_moba_creep_data SET WaypointPathId = 900110 WHERE CreatureEntry = 900010; -- Alliance melee-left
UPDATE mod_moba_creep_data SET WaypointPathId = 900120 WHERE CreatureEntry = 900011; -- Horde melee-left
UPDATE mod_moba_creep_data SET WaypointPathId = 900112 WHERE CreatureEntry = 900014; -- Alliance siege
UPDATE mod_moba_creep_data SET WaypointPathId = 900122 WHERE CreatureEntry = 900015; -- Horde siege

